// TestConstraintGateWiring_ExhaustionState_MaxRetries verifies that when
// evaluateConstraintGate exhausts MaxConstraintGateRetries, it sets:
// - constraint_gate_exhausted=true
// - constraint_gate_failed_at_commit=HEAD SHA of feature worktree
func TestConstraintGateWiring_ExhaustionState_MaxRetries(t *testing.T) {
	bareRepoPath := setupTestRepoWithMainBranch(t)
	mainDir := setupMainWorktreeWithConstraints(t, bareRepoPath, "[[max_lines]]\nname = \"file size check\"\nglob = \"*.go\"\nlimit = 5\n")
	featureName := "gate-exhaustion-max-retries"
	featureDir := constraintFailWorktree(t, bareRepoPath, featureName, 5)

	db := testutil.NewTestDB(t)
	wt := &worktree.Manager{BareRepoPath: bareRepoPath, DefaultBranch: "main"}
	o := testOrchestrator(t, db, wt)

	project := model.Project{ID: o.projectID, Name: "test", BareRepoPath: bareRepoPath}
	db.Create(&project)

	// Set up a parent task with MaxConstraintGateRetries-1 retries and past next_check
	parentID := uuid.New()
	parent := model.Task{
		ID:             parentID,
		ProjectID:      o.projectID,
		Title:          "parent",
		Description:    "test parent",
		Status:         model.StatusTestWriting,
		WorktreeBranch: "feature/" + featureName,
		Context: model.JSONField{
			"constraint_gate_retries":        float64(MaxConstraintGateRetries - 1),
			"constraint_gate_previous_failed":  float64(2),
			"constraint_gate_next_check":       time.Now().Add(-time.Hour).Format(time.RFC3339),
			"baseline_tests_checked":         true,
		},
	}
	db.Create(&parent)

	// Create a done test-phase subtask.
	sub := model.Task{
		ID:           uuid.New(),
		ProjectID:    o.projectID,
		ParentTaskID: &parentID,
		Title:        "test-sub",
		Description:  "test subtask",
		Status:       model.StatusDone,
		Phase:        "test",
	}
	db.Create(&sub)

	// Call evaluateConstraintGate to trigger max retries exhaustion
	blocked, err := o.evaluateConstraintGate(&parent)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	// Task should be blocked (true) because it exhausted retries
	if !blocked {
		t.Error("expected task to be blocked due to max retries exhaustion")
	}

	var updated model.Task
	db.First(&updated, "id = ?", parentID)

	// Task must be FAILED due to max retries exhaustion
	if updated.Status != model.StatusFailed {
		t.Errorf("expected task status to be FAILED, got %s", updated.Status)
	}

	// Check that constraint_gate_exhausted is set to true
	exhausted, hasKey := updated.Context["constraint_gate_exhausted"]
	if !hasKey {
		t.Error("expected constraint_gate_exhausted key to be present in context")
	}
	if exhausted != true {
		t.Errorf("expected constraint_gate_exhausted to be true, got %v", exhausted)
	}

	// Check that constraint_gate_failed_at_commit is set to a non-empty string
	failedAtCommit, hasKey := updated.Context["constraint_gate_failed_at_commit"]
	if !hasKey {
		t.Error("expected constraint_gate_failed_at_commit key to be present in context")
	}
	if failedAtCommit == "" || failedAtCommit == nil {
		t.Error("expected constraint_gate_failed_at_commit to be a non-empty string")
	}

	// Verify the commit SHA matches the HEAD of the feature worktree
	expectedSHA := runGitCmd(t, featureDir, "rev-parse", "HEAD")
	if failedAtCommit != strings.TrimSpace(expectedSHA) {
		t.Errorf("expected constraint_gate_failed_at_commit to match HEAD SHA of feature worktree. Got: %s, Expected: %s", failedAtCommit, strings.TrimSpace(expectedSHA))
	}
}

